import { Context, Effect, Layer, HashSet, SubscriptionRef } from 'effect';
import { ApplyTransactionError, UtxoNotFoundError, } from './model.js';
export class UnshieldedStateService extends Context.Tag('@midnight-ntwrk/wallet-sdk-unshielded-state')() {
    static createService = (stateRef) => {
        const applyTx = (tx) => SubscriptionRef.updateEffect(stateRef, (state) => Effect.gen(function* () {
            const { createdUtxos, spentUtxos, transactionResult, id } = tx;
            if (transactionResult?.status === 'FailedEntirely') {
                return yield* Effect.fail(new ApplyTransactionError({
                    tx: tx,
                    message: `Cannot apply failed a transaction with status: ${transactionResult?.status ?? 'Unknown'}`,
                }));
            }
            // @TODO: Handle partial success
            return {
                ...state,
                utxos: HashSet.union(HashSet.difference(state.utxos, HashSet.fromIterable(spentUtxos)), HashSet.fromIterable(createdUtxos)),
                pendingUtxos: HashSet.difference(state.pendingUtxos, HashSet.fromIterable(spentUtxos)),
                syncProgress: {
                    highestTransactionId: state.syncProgress?.highestTransactionId ?? 0,
                    currentTransactionId: id,
                },
            };
        }));
        const applyFailedTx = (tx) => SubscriptionRef.updateEffect(stateRef, (state) => Effect.gen(function* () {
            const { spentUtxos, transactionResult } = tx;
            if (transactionResult?.status !== 'FailedEntirely') {
                return yield* Effect.fail(new ApplyTransactionError({
                    tx: tx,
                    message: `Cannot apply failed a transaction with status: ${transactionResult?.status ?? 'Unknown'}`,
                }));
            }
            return {
                ...state,
                utxos: HashSet.union(state.utxos, HashSet.fromIterable(spentUtxos)),
                pendingUtxos: HashSet.difference(state.pendingUtxos, HashSet.fromIterable(spentUtxos)),
            };
        }));
        const spend = (utxoToSpend) => SubscriptionRef.updateEffect(stateRef, (state) => Effect.gen(function* () {
            const utxo = utxoToSpend;
            if (!HashSet.has(state.utxos, utxo)) {
                return yield* Effect.fail(new UtxoNotFoundError({ utxo: utxoToSpend }));
            }
            return {
                ...state,
                utxos: HashSet.remove(state.utxos, utxo),
                pendingUtxos: HashSet.add(state.pendingUtxos, utxo),
            };
        }));
        const updateSyncProgress = (highestTransactionId) => SubscriptionRef.update(stateRef, (state) => ({
            ...state,
            syncProgress: {
                highestTransactionId,
                currentTransactionId: state?.syncProgress?.currentTransactionId ?? 0,
            },
        }));
        const rollbackTx = (tx) => SubscriptionRef.updateEffect(stateRef, (state) => {
            const { spentUtxos } = tx;
            return Effect.succeed({
                ...state,
                utxos: HashSet.union(state.utxos, HashSet.fromIterable(spentUtxos)),
                pendingUtxos: HashSet.difference(state.pendingUtxos, HashSet.fromIterable(spentUtxos)),
            });
        });
        return UnshieldedStateService.of({
            state: stateRef.changes,
            getLatestState: () => SubscriptionRef.get(stateRef),
            applyTx,
            applyFailedTx,
            spend,
            updateSyncProgress,
            rollbackTx,
        });
    };
    static Live = () => Layer.effect(UnshieldedStateService, Effect.gen(function* () {
        const initialState = {
            utxos: HashSet.empty(),
            pendingUtxos: HashSet.empty(),
            syncProgress: undefined,
        };
        const stateRef = yield* SubscriptionRef.make(initialState);
        return UnshieldedStateService.createService(stateRef);
    }));
    static LiveWithState = (initialState) => Layer.effect(UnshieldedStateService, Effect.gen(function* () {
        const stateRef = yield* SubscriptionRef.make(initialState);
        return UnshieldedStateService.createService(stateRef);
    }));
}
